Session hijacking is a type of cyber attack where an attacker steals a user's session cookie and uses it to impersonate the user. To protect against session hijacking, you can implement several security measures. Here are some common ones:

1. **Use HTTPS**: Ensure that your application communicates over HTTPS to encrypt data in transit.
   ```plaintext
   # Enforce HTTPS in web server configuration (e.g., Apache)
   <VirtualHost *:80>
       ServerName www.example.com
       Redirect permanent / https://www.example.com/
   </VirtualHost>

   <VirtualHost *:443>
       ServerName www.example.com
       SSLEngine on
       SSLCertificateFile /path/to/your_certificate.crt
       SSLCertificateKeyFile /path/to/your_private.key
   </VirtualHost>
   ```

2. **Use Secure, HttpOnly Cookies**: Configure session cookies to be secure (sent only over HTTPS) and HttpOnly (not accessible via client-side scripts).
   ```javascript
   // Setting session cookie in Node.js with Express
   app.use(session({
       secret: 'your_secret_key',
       resave: false,
       saveUninitialized: true,
       cookie: {
           secure: true,  // Ensure the cookie is only sent over HTTPS
           httpOnly: true // Prevent client-side scripts from accessing the cookie
       }
   }));
   ```

3. **Regenerate Session ID on Login**: Regenerate the session ID after a successful login to prevent session fixation attacks.
   ```javascript
   // Example in Node.js with Express and Passport.js
   passport.serializeUser((user, done) => {
       done(null, user.id);
   });

   app.post('/login', (req, res, next) => {
       passport.authenticate('local', (err, user) => {
           if (err || !user) {
               return res.status(401).send({ message: 'Authentication failed' });
           }
           req.logIn(user, (err) => {
               if (err) { return next(err); }
               // Regenerate session ID on successful login
               req.session.regenerate(() => {
                   res.redirect('/dashboard');
               });
           });
       })(req, res, next);
   });
   ```

4. **Set Session Expiry and Inactivity Timeout**: Set a short session expiry time and an inactivity timeout to minimize the risk of session hijacking if a session is stolen.
   ```javascript
   // Example in Node.js with Express
   app.use(session({
       secret: 'your_secret_key',
       resave: false,
       saveUninitialized: true,
       cookie: {
           secure: true,
           httpOnly: true,
           maxAge: 900000 // 15 minutes
       },
       rolling: true, // Refresh the session expiry time on each request
       resaveInterval: 600000 // Save session every 10 minutes if there are changes
   }));
   ```

5. **Use Multi-Factor Authentication (MFA)**: Implement MFA to add an extra layer of security beyond just password protection.
   ```plaintext
   # Example in Node.js with Authy and Passport.js
   app.post('/login', passport.authenticate('local'), (req, res) => {
       authy.request_sms(req.user.authy_id, (err, response) => {
           if (err) { return res.status(500).send({ message: 'Failed to send verification code' }); }
           req.session.user = req.user;
           req.session.verify_code_sent = true;
           res.redirect('/verify-code');
       });
   });

   app.post('/verify-code', (req, res) => {
       const { user, verify_code_sent } = req.session;
       if (!user || !verify_code_sent) { return res.status(401).send({ message: 'Invalid request' }); }
       authy.verify(req.user.authy_id, req.body.code, (err, response) => {
           if (err) { return res.status(401).send({ message: 'Verification failed' }); }
           // MFA successful, proceed with login
           res.redirect('/dashboard');
       });
   });
   ```

6. **Monitor and Detect Suspicious Activity**: Implement logging and monitoring to detect unusual activity such as multiple failed login attempts or access from unknown devices.
   ```javascript
   // Example in Node.js using Winston for logging
   const winston = require('winston');

   const logger = winston.createLogger({
       level: 'info',
       format: winston.format.json(),
       transports: [
           new winston.transports.File({ filename: 'error.log', level: 'error' }),
           new winston.transports.File({ filename: 'combined.log' })
       ]
   });

   app.post('/login', (req, res) => {
       passport.authenticate('local', (err, user) => {
           if (err || !user) {
               logger.warn(`Failed login attempt for ${req.body.username}`);
               return res.status(401).send({ message: 'Authentication failed' });
           }
           req.logIn(user, (err) => {
               if (err) { return next(err); }
               logger.info(`User ${user.username} logged in successfully`);
               // Regenerate session ID on successful login
               req.session.regenerate(() => {
                   res.redirect('/dashboard');
               });
           });
       })(req, res, next);
   });
   ```

7. **Implement CAPTCHA**: Use CAPTCHA challenges to verify that a request is made by a human user and not an automated script.
   ```html
   <!-- Example of using reCAPTCHA in a login form -->
   <form action="/login" method="post">
       <input type="text" name="username" required>
       <input type="password" name="password" required>
       <!-- Add your reCAPTCHA widget here -->
       <div class="g-recaptcha" data-sitekey="your_site_key"></div>
       <button type="submit">Login</button>
   </form>
   ```

By implementing these security measures, you can significantly reduce the risk of session hijacking and protect your application from unauthorized access.

