import time
from functools import wraps

def rate_limit(limit, period):
    def decorator(func):
        last_called = [0.0]  # Use list to allow updates in closure

        @wraps(func)
        def wrapper(*args, **kwargs):
            elapsed = time.time() - last_called[0]
            if elapsed < period:
                remaining_time = period - elapsed
                raise Exception(f"Rate limit exceeded. Try again after {remaining_time:.2f} seconds.")
            else:
                result = func(*args, **kwargs)
                last_called[0] = time.time()
                return result
        return wrapper
    return decorator

